<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)?$from:date('Y-m-01');$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)?$to:date('Y-m-d');
$q=$conn->prepare("SELECT COUNT(*) c,COALESCE(SUM(total_amount),0) total,COALESCE(SUM(paid_amount),0) paid,COALESCE(SUM(balance),0) credit FROM sales WHERE sale_status='Completed' AND DATE(sale_date) BETWEEN ? AND ?");$q->execute([$from,$to]);$sales=$q->fetch();
$q=$conn->prepare("SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date BETWEEN ? AND ?");$q->execute([$from,$to]);$expenses=(float)$q->fetchColumn();
$q=$conn->prepare("SELECT COALESCE(SUM(amount),0) total FROM customer_payments WHERE DATE(payment_date) BETWEEN ? AND ?");$q->execute([$from,$to]);$collections=(float)$q->fetchColumn();
$q=$conn->prepare("SELECT p.product_name,SUM(si.quantity) qty,SUM(si.subtotal) revenue,SUM(si.quantity*si.buying_price) cost FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.sale_status='Completed' AND DATE(s.sale_date) BETWEEN ? AND ? GROUP BY p.id ORDER BY revenue DESC LIMIT 20");$q->execute([$from,$to]);$products=$q->fetchAll();
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?><main class="content"><style>.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:15px 0}.card,.panel{background:#fff;padding:16px;border-radius:10px;box-shadow:0 1px 4px #0001}.card strong{display:block;font-size:20px}.filter{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.filter label{font-size:12px;font-weight:700}.filter input{padding:10px;border:1px solid #dbe3ec;border-radius:7px}.btn{background:#004a99;color:#fff;border:0;padding:10px 15px;border-radius:7px;font-weight:700}.table{width:100%;border-collapse:collapse}.table th{background:#004a99;color:#fff;padding:10px;text-align:left}.table td{padding:10px;border-bottom:1px solid #e5e7eb}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.cards{grid-template-columns:1fr}}</style><h1>Reports</h1><p>Sales, collections, credit, expenses and product performance.</p><div class="panel"><form class="filter"><div><label>From</label><br><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><br><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn">Run Report</button></form></div><div class="cards"><div class="card"><strong><?=number_format((int)$sales['c'])?></strong><small>Sales</small></div><div class="card"><strong>KES <?=number_format((float)$sales['total'],2)?></strong><small>Revenue</small></div><div class="card"><strong>KES <?=number_format((float)$sales['paid'],2)?></strong><small>Collected on Sales</small></div><div class="card"><strong>KES <?=number_format((float)$sales['credit'],2)?></strong><small>New Credit</small></div><div class="card"><strong>KES <?=number_format($expenses,2)?></strong><small>Expenses</small></div></div><div class="cards"><div class="card"><strong>KES <?=number_format($collections,2)?></strong><small>Credit Collections</small></div><div class="card"><strong>KES <?=number_format((float)$sales['total']-$expenses,2)?></strong><small>Revenue Less Expenses</small></div></div><div class="panel"><h3>Top Products</h3><div style="overflow:auto"><table class="table"><thead><tr><th>Product</th><th>Units Sold</th><th>Revenue</th><th>Cost</th><th>Gross Margin</th></tr></thead><tbody><?php foreach($products as $p):$margin=(float)$p['revenue']-(float)$p['cost'];?><tr><td><?=e($p['product_name'])?></td><td><?=number_format((float)$p['qty'],0)?></td><td>KES <?=number_format((float)$p['revenue'],2)?></td><td>KES <?=number_format((float)$p['cost'],2)?></td><td>KES <?=number_format($margin,2)?></td></tr><?php endforeach;?></tbody></table></div></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>